/// One of several kinds, told apart by `_tag`. A kind this client doesn't know, from a newer API,
/// is `unknown`, with its name.
public enum Evidence: Codable, Hashable, Sendable {
    case down(DownEvidence)
    case failing(FailingEvidence)
    case stopped(StoppedEvidence)
    case unknown(String)

    private enum Kind: String, CodingKey {
        case kind = "_tag"
    }

    public init(from decoder: any Decoder) throws {
        let kind = try decoder.container(keyedBy: Kind.self).decode(String.self, forKey: .kind)
        switch kind {
        case "down": self = .down(try DownEvidence(from: decoder))
        case "failing": self = .failing(try FailingEvidence(from: decoder))
        case "stopped": self = .stopped(try StoppedEvidence(from: decoder))
        default: self = .unknown(kind)
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .down(let value):
            try value.encode(to: encoder)
            var container = encoder.container(keyedBy: Kind.self)
            try container.encode("down", forKey: .kind)
        case .failing(let value):
            try value.encode(to: encoder)
            var container = encoder.container(keyedBy: Kind.self)
            try container.encode("failing", forKey: .kind)
        case .stopped(let value):
            try value.encode(to: encoder)
            var container = encoder.container(keyedBy: Kind.self)
            try container.encode("stopped", forKey: .kind)
        case .unknown(let kind):
            var container = encoder.container(keyedBy: Kind.self)
            try container.encode(kind, forKey: .kind)
        }
    }
}

