/// One of several kinds, told apart by `_tag`. A kind this client doesn't know, from a newer API,
/// is `unknown`, with its name.
public enum TodayItem: Codable, Hashable, Sendable {
    case incident(IncidentItem)
    case error(ErrorItem)
    case slower(SlowerItem)
    case silent(SilentItem)
    case unknown(String)

    private enum Kind: String, CodingKey {
        case kind = "_tag"
    }

    public init(from decoder: any Decoder) throws {
        let kind = try decoder.container(keyedBy: Kind.self).decode(String.self, forKey: .kind)
        switch kind {
        case "incident": self = .incident(try IncidentItem(from: decoder))
        case "error": self = .error(try ErrorItem(from: decoder))
        case "slower": self = .slower(try SlowerItem(from: decoder))
        case "silent": self = .silent(try SilentItem(from: decoder))
        default: self = .unknown(kind)
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .incident(let value):
            try value.encode(to: encoder)
            var container = encoder.container(keyedBy: Kind.self)
            try container.encode("incident", forKey: .kind)
        case .error(let value):
            try value.encode(to: encoder)
            var container = encoder.container(keyedBy: Kind.self)
            try container.encode("error", forKey: .kind)
        case .slower(let value):
            try value.encode(to: encoder)
            var container = encoder.container(keyedBy: Kind.self)
            try container.encode("slower", forKey: .kind)
        case .silent(let value):
            try value.encode(to: encoder)
            var container = encoder.container(keyedBy: Kind.self)
            try container.encode("silent", forKey: .kind)
        case .unknown(let kind):
            var container = encoder.container(keyedBy: Kind.self)
            try container.encode(kind, forKey: .kind)
        }
    }
}

